import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

// Create the scene from the source file
const root = createScene();

// Apply -90 degree X-rotation for Blender Z-up coordinate space
// In Three.js: Y-up. In Blender: Z-up. Rotating -90° around X maps Y->Z.
const wrapper = new THREE.Group();
wrapper.rotation.x = -Math.PI / 2;
wrapper.add(root);

// Update all world matrices so transforms propagate correctly
wrapper.updateMatrixWorld(true);

// The built-in OBJExporter does not handle InstancedMesh.
// We need to expand InstancedMesh instances into regular Mesh objects before export.
// Also, mirrored (negative-determinant) transforms require face winding correction.

function expandInstancedMeshes(object) {
  const toRemove = [];
  const toAdd = [];

  object.traverse((child) => {
    if (child.isInstancedMesh) {
      const instancedMesh = child;
      const parent = instancedMesh.parent;
      const count = instancedMesh.count;
      const geometry = instancedMesh.geometry;
      const material = instancedMesh.material;

      for (let i = 0; i < count; i++) {
        const matrix = new THREE.Matrix4();
        instancedMesh.getMatrixAt(i, matrix);

        const mesh = new THREE.Mesh(geometry.clone(), material);
        mesh.name = instancedMesh.name + '_instance_' + i;
        mesh.applyMatrix4(matrix);

        toAdd.push({ parent, mesh });
      }

      toRemove.push({ parent, child: instancedMesh });
    }
  });

  // Remove instanced meshes and add expanded ones
  for (const { parent, child } of toRemove) {
    parent.remove(child);
  }
  for (const { parent, mesh } of toAdd) {
    parent.add(mesh);
  }
}

// Expand all InstancedMesh objects into regular Mesh objects
expandInstancedMeshes(wrapper);

// Re-update world matrices after modification
wrapper.updateMatrixWorld(true);

// Handle mirrored (negative determinant) transforms by flipping face winding.
// When a mesh's matrixWorld has a negative determinant (e.g., from a negative scale),
// the triangle winding order gets reversed, producing inverted normals in the OBJ.
// We fix this by reversing the index buffer for those meshes.
wrapper.traverse((child) => {
  if (child.isMesh) {
    const det = child.matrixWorld.determinant();
    if (det < 0) {
      const geometry = child.geometry;
      // Clone geometry so we don't mutate shared buffers
      const clonedGeometry = geometry.clone();
      const index = clonedGeometry.getIndex();
      if (index) {
        const arr = index.array;
        for (let i = 0; i < arr.length; i += 3) {
          const tmp = arr[i];
          arr[i] = arr[i + 2];
          arr[i + 2] = tmp;
        }
        index.needsUpdate = true;
      } else {
        // Non-indexed: swap vertices in each triangle
        const pos = clonedGeometry.getAttribute('position');
        const norm = clonedGeometry.getAttribute('normal');
        const uv = clonedGeometry.getAttribute('uv');
        for (let i = 0; i < pos.count; i += 3) {
          // Swap vertex 0 and vertex 2 of each triangle
          for (const attr of [pos, norm, uv]) {
            if (!attr) continue;
            const itemSize = attr.itemSize;
            for (let k = 0; k < itemSize; k++) {
              const a = attr.array[i * itemSize + k];
              const b = attr.array[(i + 2) * itemSize + k];
              attr.array[i * itemSize + k] = b;
              attr.array[(i + 2) * itemSize + k] = a;
            }
          }
        }
      }
      child.geometry = clonedGeometry;
    }
  }
});

// Export using OBJExporter
const exporter = new OBJExporter();
const objData = exporter.parse(wrapper);

// Ensure output directory exists
const outputDir = path.resolve('/root/output');
fs.mkdirSync(outputDir, { recursive: true });

const outputPath = path.join(outputDir, 'object.obj');
fs.writeFileSync(outputPath, objData);

console.log('OBJ exported to:', outputPath);
console.log('File size:', fs.statSync(outputPath).size, 'bytes');

// Quick sanity check: count vertices, normals, faces
const lines = objData.split('\n');
const vCount = lines.filter(l => l.startsWith('v ')).length;
const vnCount = lines.filter(l => l.startsWith('vn ')).length;
const fCount = lines.filter(l => l.startsWith('f ')).length;
const oCount = lines.filter(l => l.startsWith('o ')).length;
console.log(`Objects: ${oCount}, Vertices: ${vCount}, Normals: ${vnCount}, Faces: ${fCount}`);

